    const v=VY[s.st];const it={id:++s.nid,x,x0:x,y:-14,py:-14,vy:v[0]+Math.random()*(v[1]-v[0]),k,base,gold:kind==="gold",fake:kind==="fake",rev:0,ph:Math.random()*9,age:0,ghost:0};
