  const CW=150,CC=[96,60],QW=22,CMIN=1.5;          /* the worry cloud: its world width and centre in scene 0, the little grey cloud's width in III, the smallest speck */
  const WALK=50,ACT={letter:1.2,horse:1.4,guard:1.0};
  const DET=[{x:94,y:186,k:"lamp"},{x:160,y:194,k:"fire"},{x:104,y:239,k:"river"},{x:90,y:150,k:"road"},{x:77,y:92,k:"star"}];
  const RIV=[[42,232],[53,226],[66,223],[79,225],[92,231],[104,239],[119,245],[137,246],[153,243],[160,234],[157,221],[148,208],[144,196]];
  const ROADS=[[[62,122],[40,96]],[[90,112],[125,80]],[[112,170],[150,196]],[[66,176],[22,206]],[[104,130],[148,118]],[[128,160],[168,150]]];
  const HOME=[80,218],STAND={letter:[92,214],horse:[134,224],guard:[88,250]};   /* lead (32D review): the guard stands left of the campfire, so Marcus stops on his left */
  const DUTIES=()=>{const D=AR().duties||{letters:[104,205],horse:[152,214],guard:[102,250]};
    return [{k:"letter",x:D.letters[0],y:D.letters[1],hx:D.letters[0],hy:D.letters[1],r:18},
      {k:"horse",x:D.horse[0],y:D.horse[1],hx:D.horse[0]+4,hy:D.horse[1]+12,r:20},
      {k:"guard",x:D.guard[0],y:D.guard[1],hx:D.guard[0],hy:D.guard[1]-12,r:16}].map(d=>({...d,done:false}))};
